namespace ghidra.app.plugin.core.debug.platform.gdb;




using org.apache.commons.lang3.tuple;

using ghidra.app.plugin.core.debug.mapping;
using ghidra.debug.api.platform;
using ghidra.framework.plugintool;
using ghidra.program.model.lang;
using ghidra.program.util;
using ghidra.trace.model;
using ghidra.trace.model.target;

public class GdbDebuggerPlatformOpinion : AbstractDebuggerPlatformOpinion {
	public static readonly string EXTERNAL_TOOL = "gnu";
	public static readonly CompilerSpecID GCC_CSPEC_ID = new CompilerSpecID("gcc");
	public static readonly CompilerSpecID WINDOWS_CSPEC_ID = new CompilerSpecID("windows");

	private static readonly Map<Pair<string, Endian>, List<LanguageCompilerSpecPair>> CACHE =
		new();

	public static List<LanguageCompilerSpecPair> getCompilerSpecsForGnu(string arch, string os,
			Endian endian) {
		CompilerSpecID prefferedCspecId = computePreferredSpecId(os);
		lock (CACHE) {
			return CACHE.computeIfAbsent(Pair.of(arch, endian), p => {
				LanguageService langServ = DefaultLanguageService.getLanguageService();
				return langServ.getLanguageCompilerSpecPairs(
					new ExternalLanguageCompilerSpecQuery(arch, EXTERNAL_TOOL,
						endian, null, prefferedCspecId));
			});
		}
	}

	protected static CompilerSpecID computePreferredSpecId(string os) {
		string lower = os.toLowerCase();
		if (lower.contains("windows")) {
			return WINDOWS_CSPEC_ID;
		}
		// Just assume Linux (really AMD64 System V ABI)
		return GCC_CSPEC_ID;
	}

	protected static class GdbDebuggerPlatformOffer : AbstractDebuggerPlatformOffer {
		public static GdbDebuggerPlatformOffer fromArchLCSP(string arch,
				LanguageCompilerSpecPair lcsp)
    {
			return new GdbDebuggerPlatformOffer("Default GDB for " + arch, lcsp.getCompilerSpec());
		}

		public GdbDebuggerPlatformOffer(string description, CompilerSpec cSpec) : base(description, cSpec)
    {
		}

		/* @Override */
		public int getConfidence() {
			return 100;
		}

		/* @Override */
		public DebuggerPlatformMapper take(PluginTool tool, Trace trace) {
			return new GdbDebuggerPlatformMapper(tool, trace, cSpec);
		}

		/* @Override */
		public bool isCreatorOf(DebuggerPlatformMapper mapper) {
			return mapper.GetType() == typeof(GdbDebuggerPlatformMapper);
		}
	}

	protected static class GdbDebuggerPlatformMapper : DefaultDebuggerPlatformMapper {
		public GdbDebuggerPlatformMapper(PluginTool tool, Trace trace, CompilerSpec cSpec) : base(tool, trace, cSpec)
    {
		}
		// TODO: eflags<->rflags for amd64 / x86-64
	}

	protected Set<GdbDebuggerPlatformOffer> offersForLanguageAndCSpec(string arch, Endian endian,
			LanguageCompilerSpecPair lcsp)
    {
		return Set.of(GdbDebuggerPlatformOffer.fromArchLCSP(arch, lcsp));
	}

	/* @Override */
	protected Set<DebuggerPlatformOffer> getOffers(TraceObject @object, long snap, TraceObject env,
			string debugger, string arch, string os, Endian endian, bool includeOverrides) {
		if (debugger == null || !"gdb".equals(debugger.toLowerCase())) {
			return Set.of();
		}
		return getCompilerSpecsForGnu(arch, os, endian).stream().flatMap(lcsp => {
			try {
				return offersForLanguageAndCSpec(arch, endian, lcsp).stream();
			}
			catch (Exception e) when (e is CompilerSpecNotFoundException or LanguageNotFoundException) {
				throw new AssertionError(e);
			}
		}).collect(Collectors.toSet());
	}
}
